import itertools

def get_neighbors(r, c, R, C):
    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < R and 0 <= nc < C:
            yield nr, nc

def count_good_paths(board, R, C):
    W = [[0]*C for _ in range(R)]
    # We must process fields in increasing order of their values
    cells = []
    for r in range(R):
        for c in range(C):
            cells.append((board[r][c], r, c))
    cells.sort()

    for val, r, c in cells:
        # Check if (r, c) is a local minimum
        is_local_min = True
        for nr, nc in get_neighbors(r, c, R, C):
            if board[nr][nc] < val:
                is_local_min = False
                break

        if is_local_min:
            W[r][c] = 1
        else:
            s = 0
            for nr, nc in get_neighbors(r, c, R, C):
                if board[nr][nc] < val:
                    s += W[nr][nc]
            W[r][c] = s

    return sum(sum(row) for row in W)

def solve_small(R, C):
    min_paths = float('inf')
    import itertools
    for p in itertools.permutations(range(1, R*C + 1)):
        board = [p[i*C:(i+1)*C] for i in range(R)]
        min_paths = min(min_paths, count_good_paths(board, R, C))
    return min_paths

print(f"1x1: {solve_small(1, 1)}")
print(f"1x2: {solve_small(1, 2)}")
print(f"1x3: {solve_small(1, 3)}")
print(f"2x2: {solve_small(2, 2)}")

