def find_best_board(R, C):
    import itertools
    min_paths = float('inf')
    best_board = None
    for p in itertools.permutations(range(1, R*C + 1)):
        board = [p[i*C:(i+1)*C] for i in range(R)]
        paths = count_good_paths(board, R, C)
        if paths < min_paths:
            min_paths = paths
            best_board = board
    return best_board, min_paths

